export const winChatSource='https://www.aiwin.com.tw/products/winchat';
const symbols={document:'M7 3h7l4 4v14H7z M14 3v5h5 M10 12h5 M10 16h5',image:'M3 4h18v16H3z M3 16l6-6 4 4 3-3 5 6 M15 8h.01',brain:'M12 5c-3-5-7-1-6 2-5 0-5 8-1 9-1 5 6 6 7 2V5z M12 5c3-5 7-1 6 2 5 0 5 8 1 9 1 5-6 6-7 2 M7 10c3-1 4 2 2 4 M17 10c-3-1-4 2-2 4',search:'M15 15l6 6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',database:'M4 6c0-5 16-5 16 0s-16 5-16 0v12c0 5 16 5 16 0V6 M4 12c0 5 16 5 16 0',skill:'M9 3h6v5h6v7h-6v6H9v-6H3V8h6z',check:'M4 12l5 5L20 6',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',chat:'M3 4h18v13H9l-6 4z M7 9h10 M7 13h6',chart:'M3 3v18h18 M6 15l4-6 4 3 6-8',arrow:'M4 12h16 M14 6l6 6-6 6',globe:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M2 12h20 M12 2c-6 5-6 15 0 20 6-5 6-15 0-20',people:'M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 22v-4c0-7 14-7 14 0v4 M17 3a4 4 0 0 1 0 8 M18 14c4 0 4 4 4 8'};
const icon=id=>`<svg class="wc-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${symbols[id]||symbols.brain}"/></svg>`;
const kicker=text=>`<p class="wc-kicker"><i></i>${text}</p>`;
const tag=(name,sub)=>`<div class="wc-topic-mark"><b>${name}</b><span>${sub}</span></div>`;
const topics=[
 {tag:'RAG',label:'企業的記憶',title:'不只讀文字。<br><em>也看懂圖像。</em>',copy:'文字、圖片、圖表與文件脈絡，<br>一起成為可檢索的企業知識。',points:[['VLM','讀懂圖片、圖表與頁面內容'],['LLM + Embedding','理解文字，建立知識索引'],['來源引用','讓回答有依據，也能回到原文']],note:'重點為使用者補充的多模態 RAG：VLM 處理圖像，LLM 理解文字，Embedding 建立檢索表示。動畫的維修文件、問題與答案均為情境示意，不是客戶資料或實測。官網支持文件解析、多知識庫、Vector／Hybrid／GraphRAG 與引用來源。'},
 {tag:'AGENT',label:'思考與協作',title:'從一個問題，<br><em>走向完整任務。</em>',copy:'把知識、即時資料與工具連起來，<br>協助分析、整理與決策。',points:[['理解目標','把工作需求拆成可執行的步驟'],['串接系統','結合知識庫、資料庫與企業流程'],['彙整結果','產出摘要與看板，交回人員使用']],note:'以現場狀況摘要示意 Agent 任務協作，強調檢索、資料查詢、整理回覆。官網支持 AI Agent 多步推理、MySQL／PostgreSQL／CSV 資料源、監控看板與 Web API。示意不是即時監控，不宣稱自動控制設備或保證推理正確。'},
 {tag:'SKILL',label:'可組合的技能',title:'把專業做法，<br><em>變成可用的技能。</em>',copy:'知識工具與系統工具，<br>讓 Agent 依任務調用所需能力。',points:[['工具包管理','依工作需求開啟對應技能'],['權限範圍','設定工具參數與可存取資源'],['重複組合','把專業能力用在不同企業情境']],note:'官網技能頁支持工具包與單項工具啟停、工具參數及權限範圍。用客服維修、新人培訓、現場巡檢呈現組合方向，不宣稱可自行學會技能、保證所有外部系統現成支援。'}
];
export const winChatTopics=topics;
function brain(){
 const left='M394 117C370 75 310 76 285 112C245 102 208 133 213 174C169 188 154 236 181 268C168 306 204 343 242 339C261 381 308 389 337 356C367 371 394 344 394 309Z';
 let nodes='',links='';const pts=[];
 for(let i=0;i<230;i++){const x=175+((i*137.508)%450),y=85+((i*83.317)%310);pts.push([x,y]);nodes+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${i%9===0?2.5:1.25}" style="--i:${i%12}"/>`;if(i>0){const near=pts.slice(0,-1).map(p=>({p,d:Math.hypot(p[0]-x,p[1]-y)})).filter(n=>n.d<43).sort((a,b)=>a.d-b.d).slice(0,2);near.forEach(({p})=>links+=`<path d="M${p[0]} ${p[1]}L${x} ${y}"/>`);}}
 const folds='M289 115C269 142 291 163 269 185S232 192 240 223S277 242 256 275S266 318 294 324 M351 117C319 147 337 171 311 194S291 230 316 246S336 278 314 298S320 329 336 355 M214 175C242 157 253 174 269 185 M182 267C208 249 232 252 256 275 M242 339C234 308 259 299 270 297 M394 182C361 169 339 197 359 220S376 252 354 271S354 313 393 309';
 return `<svg class="wc-brain" viewBox="0 0 800 500" aria-hidden="true"><defs><linearGradient id="wc-brain-fill" x2="1" y2="1"><stop stop-color="#bda4ed" stop-opacity=".19"/><stop offset="1" stop-color="#4b247d" stop-opacity=".06"/></linearGradient><linearGradient id="wc-brain-line"><stop stop-color="#91b8e8"/><stop offset=".5" stop-color="#e7d9ff"/><stop offset="1" stop-color="#9777d2"/></linearGradient><clipPath id="wc-brain-clip"><path d="${left}"/><path d="${left}" transform="translate(800 0) scale(-1 1)"/></clipPath></defs><ellipse class="wc-brain-orbit" cx="400" cy="263" rx="332" ry="91" transform="rotate(-17 400 263)"/><ellipse class="wc-brain-orbit orbit-two" cx="400" cy="263" rx="316" ry="91" transform="rotate(21 400 263)"/><g fill="url(#wc-brain-fill)" stroke="url(#wc-brain-line)" stroke-width="1.6"><path d="${left}"/><path d="${left}" transform="translate(800 0) scale(-1 1)"/></g><g class="wc-cortex"><path d="${folds}"/><path d="${folds}" transform="translate(800 0) scale(-1 1)"/></g><g clip-path="url(#wc-brain-clip)" class="wc-synapses">${links}${nodes}<path class="wc-neural-pulse" d="M180 270Q260 150 320 245T420 205T610 270 M250 350Q300 230 360 160T545 350"/></g><path class="wc-brain-stem" d="M394 307V396Q400 423 405 396V307 M400 417V456"/><circle class="wc-brain-core" cx="400" cy="252" r="10"/><circle class="wc-core-ring" cx="400" cy="252" r="24"/><g class="wc-brain-labels"><text x="95" y="153">MEMORY</text><text x="620" y="172">REASONING</text><text x="550" y="416">ACTION</text></g></svg>`;
}
const applications=()=>`<div class="wc-applications">${[['chat','客服與維修','找知識 · 查圖解'],['people','新人與培訓','學流程 · 問規範'],['chart','現場與巡檢','看狀態 · 做摘要']].map(a=>`<div>${icon(a[0])}<strong>${a[1]}</strong><small>${a[2]}</small></div>`).join('')}</div>`;
function drawing(){return `<svg class="wc-drawing" viewBox="0 0 300 190" aria-hidden="true"><g stroke="#8196bc" stroke-width="1.5" fill="none"><path d="M55 122L130 153 243 91 167 57z M55 122V68l76 31v54 M55 68l112-62 76 30v55 M131 99l112-63 M80 79v56 M109 92v54 M159 84v54 M186 69v54 M214 53v54"/><path d="M87 38l73 30 52-29-73-29z M87 38V59l73 30V68 M160 89l52-29V39"/><circle cx="202" cy="90" r="9"/><path d="M211 90h53v47"/></g><rect class="wc-image-target" x="180" y="68" width="44" height="44" rx="6"/><circle cx="202" cy="90" r="3" fill="#b998f6"/></svg>`;}
function rag(){return `<div class="wc-art wc-rag"><div class="wc-art-bar">${tag('RAG','MULTIMODAL KNOWLEDGE')}<span>多模態知識理解</span></div><div class="wc-rag-flow"><div class="wc-doc"><div class="wc-doc-head">${icon('document')}<span>設備維修手冊</span><small>PDF</small></div><div class="wc-doc-lines"><i></i><i></i><i></i></div><div class="wc-doc-picture">${drawing()}<span>圖像 / 圖表</span><i class="wc-image-scan"></i></div><div class="wc-doc-lines short"><i></i><i></i></div></div><div class="wc-understanding"><div class="wc-understand vlm">${icon('image')}<div><b>VLM</b><span>看懂圖像與圖表</span></div><i></i></div><div class="wc-understand llm">${icon('document')}<div><b>LLM</b><span>理解文字與脈絡</span></div><i></i></div><div class="wc-embedding"><span>Embedding</span><div>${Array.from({length:14},(_,i)=>`<i style="--i:${i};--h:${24+i*17%70}%"></i>`).join('')}</div><small>建立可檢索的知識索引</small></div></div><div class="wc-knowledge"><div class="wc-knowledge-symbol">${icon('database')}<i></i><i></i></div><strong>企業知識庫</strong><div class="wc-index-types"><span>Vector</span><span>Hybrid</span><span>GraphRAG</span></div><div class="wc-retrieval">${icon('search')}知識檢索<span>→</span></div></div></div><div class="wc-answer"><div class="wc-question">${icon('chat')}這張圖的部件，對應哪份維修說明？</div><div class="wc-answer-body"><span class="wc-answer-mark">W</span><div><strong>連起圖像、文件與答案。</strong><p>定位圖中部件，帶回相關文件脈絡與引用來源。</p><span class="wc-citation">${icon('document')}維修手冊 · 對應章節 <b>↗</b></span></div><span class="wc-sample">情境示意</span></div></div></div>`;}
function agent(){return `<div class="wc-art wc-agent"><div class="wc-art-bar">${tag('AGENT','REASONING TO ACTION')}<span>把需求串成工作</span></div><div class="wc-task"><span>工作目標</span><strong>幫我整理今天的設備狀況，<br>並帶出需要留意的項目。</strong><i></i></div><div class="wc-agent-process">${[['01','search','查知識','SOP / 歷史紀錄'],['02','database','連資料','資料庫 / 企業系統'],['03','brain','做分析','整合脈絡與結果']].map((a,i)=>`<div style="--i:${i}"><span>${a[0]}</span>${icon(a[1])}<strong>${a[2]}</strong><small>${a[3]}</small></div>`).join('<b class="wc-process-link">→</b>')}</div><div class="wc-agent-output"><div class="wc-report"><div>${icon('document')}<b>現場工作摘要</b><span>READY</span></div><p><i></i>整理運轉紀錄與關注項目</p><p><i></i>連結相關規範與知識來源</p><p><i></i>提供人員判讀與後續處理</p></div><div class="wc-mini-dashboard"><div><b>營運資訊</b><span>示意</span></div><svg viewBox="0 0 320 140" aria-hidden="true"><path class="wc-chart-grid" d="M0 25H320 M0 70H320 M0 115H320"/><path class="wc-chart-fill" d="M0 111L40 91 80 101 120 65 160 78 200 40 240 51 280 20 320 35V140H0Z"/><path class="wc-chart-line" d="M0 111L40 91 80 101 120 65 160 78 200 40 240 51 280 20 320 35"/></svg><span>資料 × 知識 × 洞察</span></div></div><small class="wc-art-caption">任務協作情境示意</small></div>`;}
function skill(){return `<div class="wc-art wc-skill"><div class="wc-art-bar">${tag('SKILL','COMPOSABLE EXPERTISE')}<span>讓能力可以被調用</span></div><div class="wc-toolkit"><div class="wc-toolkit-head">${icon('skill')}<div><span>企業工具包</span><strong>把專業接到 Agent</strong></div><span class="wc-skill-state">授權範圍內</span></div><div class="wc-tools">${[['database','知識檢索','知識庫與文件'],['chart','資料查詢','企業資料來源'],['document','工作摘要','彙整任務結果']].map((a,i)=>`<div style="--i:${i}">${icon(a[0])}<strong>${a[1]}</strong><span>${a[2]}</span><i class="wc-toggle"></i></div>`).join('')}</div><div class="wc-toolkit-footer">${icon('shield')}工具參數 · 存取範圍 · 啟用控制</div></div><div class="wc-skill-routing"><span></span><b>Agent 依任務組合技能</b><span></span></div>${applications()}<small class="wc-art-caption">應用組合示意 · 依企業系統與權限配置</small></div>`;}
function overview(){return {story:`${kicker('WINCHAT / THE THINKING CHAPTER')}<h1 class="wc-heading">從記住，<br>到知道<em>怎麼做。</em></h1><p class="wc-intro-copy">學會看見與分析之後，<br>讓知識成為下一步行動。</p><div class="wc-topic-links">${topics.map((t,i)=>`<button data-journey="select" data-topic="${i}"><span>0${i+1}</span><div><b>${t.tag}</b><strong>${t.label}</strong></div><i>↗</i></button>`).join('')}</div><p class="wc-worlds">客服維修 / 新人培訓 / 現場巡檢</p>`,detail:`<div class="wc-overview-visual"><div class="wc-brain-heading"><span>MEMORY. REASONING. ACTION.</span><strong>逐漸成熟的企業大腦</strong></div>${brain()}<div class="wc-neural-trails"><i></i><i></i><i></i></div></div>`};}
export function winChatUI(state){
 if(state.phase==='overview')return {...overview(),key:'overview',note:'接續感知與專案學習：企業的大腦開始具備記憶、思考與技能。三塊依序深入，全部完成後融合成 WinChat。涵蓋客服維修、新人培訓與現場巡檢。'};
 if(['selecting','focus'].includes(state.phase)){const t=topics[state.selected];return {key:'topic-'+state.selected,story:`${kicker(`0${state.selected+1} / ${t.tag} — ${t.label}`)}<h1 class="wc-heading">${t.title}</h1><p class="wc-intro-copy">${t.copy}</p><div class="wc-points">${t.points.map((a,i)=>`<div><span>0${i+1}</span><section><b>${a[0]}</b><p>${a[1]}</p></section></div>`).join('')}</div>`,detail:`<div class="wc-topic-stage">${[rag,agent,skill][state.selected]()}</div>`,note:t.note};}
 if(state.phase==='fusing')return {key:'fusing',story:'',detail:`<div class="wc-fusion"><p class="wc-kicker">KNOWLEDGE BECOMES CAPABILITY</p><h1>記憶、思考、技能。<br><em>組成企業的智慧。</em></h1><div class="wc-fusion-halo"><i></i><i></i><i></i><i></i></div><div class="wc-fusion-words"><span>RAG</span><b>＋</b><span>Agent</span><b>＋</b><span>Skill</span></div></div>`,note:'三塊能力共同旋入中心，融合後才揭曉 WinChat。'};
 return {key:'born',story:`${kicker('MEMORY + REASONING + ACTION')}<h1 class="wc-product-name">WinChat<span>企業知識 AI 協作平台</span></h1><p class="wc-intro-copy">從看懂企業知識，<br>到協助每一份工作。</p><div class="wc-born-points"><span>${icon('image')}多模態知識理解</span><span>${icon('brain')}Agent 任務協作</span><span>${icon('skill')}Skill 能力組合</span><span>${icon('shield')}本地 / 私有環境部署</span></div><button class="wc-proof-button" data-winchat-evidence="answer">查看 WinChat 產品介面 <span>↗</span></button>`,detail:`<div class="wc-born-orbit"></div><div class="wc-born-applications"><div class="wc-apps-heading"><span>ONE PLATFORM. MANY POSSIBILITIES.</span><strong>企業的每一種工作，都能連起來。</strong></div>${[['chat','客服與維修','找出零件圖解，<br>連起產品與維修知識。','圖文問答 / 知識引用'],['people','新人與培訓','遇到問題就提問，<br>把流程與經驗傳下去。','SOP 查詢 / 教育培訓'],['chart','現場與巡檢','把資料彙整成洞察，<br>協助掌握現場狀況。','資料查詢 / 戰情看板']].map((a,i)=>`<article class="wc-application-card" style="--i:${i}"><span>0${i+1}</span>${icon(a[0])}<h2>${a[1]}</h2><p>${a[2]}</p><small>${a[3]}</small></article>`).join('')}</div>`,note:'WinChat 由三塊能力誕生。應用涵蓋客服維修、新人培訓、現場巡檢。產品介面按鈕可放大官網的 RAG 問答與 Skill 管理畫面，非現場連線；多模態 RAG 依使用者補充。下一幕回到原本的協作成形。'};
}

export function winChatEvidence(view='answer'){
 const skills=view==='skills';
 return `<div class="wc-proof"><div class="wc-proof-top"><span>WINCHAT / OFFICIAL PRODUCT VIEW</span><h2 id="case-heading">${skills?'技能與工具包管理':'知識問答，附上引用來源。'}</h2><p>AIWin 官方產品介面</p><div><button data-winchat-evidence="answer" aria-pressed="${!skills}">RAG 知識問答</button><button data-winchat-evidence="skills" aria-pressed="${skills}">Skill 工具管理</button></div></div><img src="./assets/winchat/${skills?'skills':'answer'}.webp" alt="${skills?'WinChat 技能管理：知識工具、系統工具與啟用控制':'WinChat RAG 知識問答與參考來源'}"/><a href="${winChatSource}" target="_blank" rel="noopener">資料來源：慧穩科技 WinChat 產品頁 ↗</a></div>`;
}
